using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using IndianOceanAssets.ShooterSurvival;
public static class VerifyExtraHazardsCycle02{
 static Chapter45Director d;static PlayerScript p;static Chapter45Hazard h;static string output;static bool safe,started;static float begin,hp,lane,warning=-1,bodyAt=-1;static int frame;static List<object> samples=new();const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static string Json(object x)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{x});
 static void Set(object o,string p,object v)=>o.GetType().GetField("<"+p+">k__BackingField",F).SetValue(o,v);static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Main(string hazard,bool safeLane,string folder){output=folder;Directory.CreateDirectory(output);safe=safeLane;d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();p=d.Player;h=d.hazards.Single(x=>x.name==hazard);UnityEngine.Object.FindFirstObjectByType<CanvasScript>().PlayerPressedStartButton();var overlay=UnityEngine.Object.FindFirstObjectByType<CombatHarness>();if(overlay!=null)typeof(CombatHarness).GetField("overlayVisible",F).SetValue(overlay,false);foreach(var e in d.encounters){e.Retire();Set(e,"Complete",true);}foreach(var other in d.hazards)if(other!=h){other.manualOnly=true;other.Cancel();}p.canShoot=false;foreach(var w in p.GetComponentsInChildren<WeaponScript>(true))w.enabled=false;if(d.chapter==5)Set(d,"CurrentSegment",Array.FindIndex(d.route.segments,s=>s.floor==4));foreach(var choice in d.choices)choice.Commit(h.requiredChoice==1?2:-2);float distance=h.distance-h.warningDistance-2;Set(d,"Distance",distance);Set(d,"CurrentSegment",d.route.SegmentAt(distance));d.Sample(h.distance,out var hazardCenter,out var hazardForward);lane=safe?h.safeLane:Vector3.Dot(h.body.position-hazardCenter,Vector3.Cross(Vector3.up,hazardForward));d.Sample(distance,out var center,out var forward);p.ApplyContinuousRoutePose(center+Vector3.up*d.footOffset,forward,lane);Physics.SyncTransforms();begin=d.Elapsed;hp=p.currentHealth;warning=bodyAt=-1;frame=-1;samples.Clear();started=true;EditorApplication.update+=Tick;return new{started,output,safe,lane,hazard};}
 static void Tick(){if(!started||!EditorApplication.isPlaying)return;EditorApplication.QueuePlayerLoopUpdate();if(frame==Time.frameCount)return;frame=Time.frameCount;float t=d.Elapsed-begin;if(h.Triggered&&warning<0){warning=t;ScreenCapture.CaptureScreenshot(Path.Combine(output,"warning.png"));}if(h.Active&&bodyAt<0){bodyAt=t;ScreenCapture.CaptureScreenshot(Path.Combine(output,"active.png"));}samples.Add(new{t,d.Distance,lane=d.Lane,h.Active,h.Contacts,h.Triggered,health=p.currentHealth,player=V(p.transform.position),playerCollider=p.GetComponent<Collider>()==null?null:new{center=V(p.GetComponent<Collider>().bounds.center),size=V(p.GetComponent<Collider>().bounds.size)},body=V(h.body.position),hitboxes=h.body.GetComponentsInChildren<Collider>(true).Select(c=>new{c.name,c.enabled,c.isTrigger,layer=c.gameObject.layer,center=V(c.bounds.center),size=V(c.bounds.size),c.gameObject.activeInHierarchy}).ToArray()});if(p.currentHealth>0&&t<8)return;bool passed=warning>=0&&bodyAt-warning>=1.15f&&(safe?h.Contacts==0&&p.currentHealth==hp&&d.Distance>h.distance+8:h.Contacts==1&&p.currentHealth<hp);File.WriteAllText(Path.Combine(output,"result.json"),Json(new{passed,hazard=h.name,safe,warning,bodyAt,warningLead=bodyAt-warning,h.Contacts,initialHealth=hp,health=p.currentHealth,initialLane=lane,d.Distance,manualDamage=false,manualHazardHit=false,manualHazardTick=false,initialPlacementOnly=true,samples,timeline=d.Timeline.ToArray()}));ScreenCapture.CaptureScreenshot(Path.Combine(output,"end.png"));started=false;EditorApplication.update-=Tick;}
}
